    out = mrt.setfield(out, 'Lp', ((mrt.field(c, 'Lw') + mrt.field(c, 'Dc')) - mrt.field(out, 'Atotal')))
    # m:139  out.Lp_longterm_applied = ~isempty(c.C0);
