    out = mrt.setfield(out, 'LpA_bands', (mrt.field(out, 'Lp') + mrt.field(b, 'wA')))
    # m:141  if out.Lp_longterm_applied, out.LpA_bands = out.LpA_bands - out.Cmet; end  % Formula (7), A-weighted only
    if mrt.truth(mrt.field(out, 'Lp_longterm_applied')):
        # m:141  if out.Lp_longterm_applied, out.LpA_bands = out.LpA_bands - out.Cmet; end  % Formula (7), A-weighted only
        out = mrt.setfield(out, 'LpA_bands', (mrt.field(out, 'LpA_bands') - mrt.field(out, 'Cmet')))
    # m:142  out.Lp_broadband  = nb_energy_sum(out.Lp);        % 63-8000 Hz bands only, unweighted
    out = mrt.setfield(out, 'Lp_broadband', nb_energy_sum(mrt.field(out, 'Lp')))
